function ringRouter(operations) {
  let servers = [];
  const results = [];
  for (const operation of operations) {
    if (operation[0] === "add") {
      const taken = servers.some((s) => s.name === operation[1] || s.position === operation[2]);
      if (!taken) servers.push({ name: operation[1], position: operation[2] });
      results.push(!taken);
    } else if (operation[0] === "remove") {
      const before = servers.length;
      servers = servers.filter((s) => s.name !== operation[1]);
      results.push(servers.length !== before);
    } else {
      let best = null;
      let lowest = null;
      for (const s of servers) {
        if (lowest === null || s.position < lowest.position) lowest = s;
        if (s.position >= operation[1] && (best === null || s.position < best.position)) best = s;
      }
      const chosen = best !== null ? best : lowest;
      results.push(chosen === null ? null : chosen.name);
    }
  }
  return results;
}

function ringRouter(operations) {
  const positions = [];
  const names = [];
  const where = new Map();
  const lowerBound = (target) => {
    let low = 0;
    let high = positions.length;
    while (low < high) {
      const mid = low + ((high - low) >> 1);
      if (positions[mid] >= target) high = mid;
      else low = mid + 1;
    }
    return low;
  };
  const results = [];
  for (const operation of operations) {
    if (operation[0] === "add") {
      const at = lowerBound(operation[2]);
      if (where.has(operation[1]) || positions[at] === operation[2]) {
        results.push(false);
      } else {
        positions.splice(at, 0, operation[2]);
        names.splice(at, 0, operation[1]);
        where.set(operation[1], operation[2]);
        results.push(true);
      }
    } else if (operation[0] === "remove") {
      if (!where.has(operation[1])) {
        results.push(false);
      } else {
        const at = lowerBound(where.get(operation[1]));
        positions.splice(at, 1);
        names.splice(at, 1);
        where.delete(operation[1]);
        results.push(true);
      }
    } else if (positions.length === 0) {
      results.push(null);
    } else {
      const at = lowerBound(operation[1]);
      results.push(names[at === positions.length ? 0 : at]);
    }
  }
  return results;
}
